<!-- 文件作用：按先行设计统一展示订单费用记录与双方协商，使用独立补款/原路退款及只读管理证据。 -->
<template>
  <view class="order-adjustments">
    <view class="adjustment-heading"><text class="adjustment-title">费用协商</text></view>
    <view class="adjustment-totals"><view class="adjustment-total-row"><text>原订单金额</text><text>¥{{ money(totals.original) }}</text></view><view class="adjustment-total-row"><text>累计补款</text><text class="adjustment-positive">+ ¥{{ money(totals.extra) }}</text></view><view class="adjustment-total-row"><text>已退差额</text><text>− ¥{{ money(totals.refunded) }}</text></view><view class="adjustment-total-row adjustment-total-net"><text>当前订单金额</text><text>¥{{ money(totals.net) }}</text></view></view>
    <view v-if="canIncrease||canDecrease" class="adjustment-new"><button v-if="canIncrease" class="btn-secondary btn-small adjustment-new-button" :disabled="busy" @click="openCreate('increase')"><Icon name="plus" :size="16"/>发起加价</button><button v-if="canDecrease" class="btn-secondary btn-small adjustment-new-button" :disabled="busy" @click="openCreate('decrease')">协商减价<Icon name="arrow" :size="14"/></button></view>
    <view v-if="error" class="adjustment-error" @click="load">{{ error }} · 点击重试</view><text v-else-if="loading&&!records.length" class="adjustment-note">正在读取费用记录…</text><text v-else-if="!records.length" class="adjustment-note">双方协商一致后，可在这里调整费用。</text>
    <view v-for="record in records" :key="record.id" :class="['adjustment-record',{'adjustment-record-pending':adjustmentPending(record)}]">
      <view class="adjustment-record-heading"><text class="adjustment-record-title">{{ record.kind==='increase'?'增加费用':'减少费用' }} · ¥{{ money(record.amount_cents) }}</text><text :class="['adjustment-status',{'adjustment-status-current':adjustmentPending(record)}]">{{ adjustmentStatus(record.status) }}</text></view>
      <text class="adjustment-reason">{{ record.reason }}</text><text class="adjustment-note">{{ record.proposer_name||'订单参与者' }} 发起 · {{ time(record.created_at) }}</text><view class="adjustment-consent"><text>买家{{ record.buyer_agreed?'已同意':'待同意' }}</text><text>打手{{ record.provider_agreed?'已同意':'待同意' }}</text></view>
      <text v-if="record.failure_reason" class="adjustment-error">{{ record.failure_reason }}</text>
      <text v-if="record.status==='refunding'" class="adjustment-note">按原付款逐笔退还，实际到账以微信和钱包记录为准。</text><text v-else-if="record.status==='paying'" class="adjustment-note">正在核验原补款结果，请勿换单重复支付。</text><text v-else-if="record.expires_at&&['proposed','awaiting_payment'].includes(record.status)" class="adjustment-note">有效期至 {{ time(record.expires_at) }}</text>
      <view class="adjustment-record-actions"><button v-if="canRespond(record,'reject')" class="text-btn adjustment-secondary" :disabled="busy" @click="prepare(record,'reject')">拒绝</button><button v-if="canRespond(record,'withdraw')" class="text-btn adjustment-secondary" :disabled="busy" @click="prepare(record,'withdraw')">撤回方案</button><button v-if="canRespond(record,'accept')" class="btn btn-small adjustment-record-primary" :disabled="busy" @click="prepare(record,'accept')">{{ record.kind==='increase'?'同意加价':'同意减价并退差' }}</button><button v-if="canPay(record)" class="btn btn-small adjustment-record-primary" :disabled="busy" @click="openPay(record)">确认补款 ¥{{ money(record.amount_cents) }}</button><button v-if="canSynchronize()&&['paying','refunding','awaiting_payment'].includes(record.status)" class="text-btn" :disabled="busy" @click="synchronize(record)">同步原单</button></view>
    </view>
    <text v-if="processing" class="adjustment-warning">费用资金处理中，验收和结算暂停，仍可在订单聊天室沟通。</text><text class="adjustment-note adjustment-footer-note">订单费率保持不变。微信付款按原路退还；余额付款退回原余额分区。</text>
    <UniPopup ref="popup" type="bottom" :animation="false" :is-mask-click="!busy" background-color="transparent" :safe-area="false" @change="popupChanged"><scroll-view scroll-y class="adjustment-sheet-scroll"><view class="adjustment-sheet"><view class="adjustment-sheet-heading"><text class="adjustment-sheet-title">{{ dialogTitle }}</text><button class="text-btn" :disabled="busy" @click="close">关闭</button></view>
      <template v-if="dialog==='create'"><text class="adjustment-note">{{ kind==='increase'?'买家同意并补款成功后，订单金额才会增加。':'对方同意后按原付款退差，不使用商家转账替代退款。' }}</text><view class="adjustment-field"><text class="adjustment-field-label">{{ kind==='increase'?'加价差额':'退还差额' }}（元）</text><view class="adjustment-amount-field"><text>¥</text><input v-model="amount" class="adjustment-amount-input" type="digit" maxlength="12" placeholder="0.00" :disabled="busy"/></view></view><view class="adjustment-field"><text class="adjustment-field-label">协商原因</text><textarea v-model="reason" class="input adjustment-reason-input" maxlength="500" placeholder="说明增加/减少的服务内容，作为双方的协商依据" :disabled="busy"/></view><view class="adjustment-sheet-summary"><text>当前订单金额</text><text>¥{{ money(order.amount_cents) }}</text></view></template>
      <template v-else-if="selected"><text class="adjustment-sheet-amount">{{ selected.kind==='increase'?'+':'−' }} ¥{{ money(selected.amount_cents) }}</text><text class="adjustment-reason">{{ selected.reason }}</text><view class="adjustment-sheet-summary"><text>当前订单金额</text><text>¥{{ money(order.amount_cents) }}</text></view><view class="adjustment-sheet-summary"><text>调整后金额</text><text>¥{{ money(order.amount_cents+(selected.kind==='increase'?selected.amount_cents:-selected.amount_cents)) }}</text></view>
        <template v-if="dialog==='pay'"><text class="adjustment-field-label adjustment-channel-heading">选择支付方式</text><view class="adjustment-channels"><button :class="['adjustment-channel',{'adjustment-channel-selected':channel==='wechat'}]" :disabled="busy" @click="channel='wechat'"><Icon name="weixin" :size="22"/><text class="adjustment-channel-copy">微信支付</text><Icon :name="channel==='wechat'?'checkbox-filled':'circle'" :size="20"/></button><button :class="['adjustment-channel',{'adjustment-channel-selected':channel==='balance'}]" :disabled="busy||!wallet||wallet.spendable_cents<selected.amount_cents" @click="channel='balance'"><Icon name="wallet" :size="22"/><view class="adjustment-channel-copy"><text>钱包余额</text><text class="adjustment-note">{{ walletLoading?'正在读取…':wallet?'可消费 ¥'+money(wallet.spendable_cents):'余额读取失败' }}</text></view><Icon :name="channel==='balance'?'checkbox-filled':'circle'" :size="20"/></button></view><text v-if="walletError" class="adjustment-error">{{ walletError }}</text><text class="adjustment-note">取消付款不会改变原价，可稍后继续或同步原补款单。</text></template>
        <text v-else class="adjustment-note adjustment-dialog-note">{{ dialog==='accept'?(selected.kind==='increase'?'同意后仍需买家确认付款，核验成功才增加订单金额。':'你同意本次退差。退款会按原付款逐笔处理，处理期间暂停验收和结算。'):dialog==='reject'?'拒绝只结束本次方案，不改变当前金额和履约阶段。':'撤回尚未付款的方案，原订单继续履约。已发生的资金不可通过撤回抹除。' }}</text>
      </template>
      <text v-if="formError" class="adjustment-error adjustment-form-error">{{ formError }}</text><view class="action-footer adjustment-dialog-actions"><button class="text-btn" :disabled="busy" @click="close">取消</button><button class="btn adjustment-confirm" :disabled="busy" @click="confirm">{{ busy?'正在处理…':confirmLabel }}</button></view>
    </view></scroll-view></UniPopup>
  </view>
</template>
<script setup lang="ts">
import {computed,nextTick,ref,watch} from 'vue'
import UniPopup from '@dcloudio/uni-ui/lib/uni-popup/uni-popup.vue'
import Icon from './Icon.vue'
import {useOrderAdjustments} from '../lib/use-order-adjustments'
import {adjustmentStatus,adjustmentPending,adjustmentFundsPending,adjustmentTotals} from '../lib/order-adjustments'
import {money,time} from '../lib/format'
import type {Order} from '../types/models'
const props=defineProps<{order:Order}>(),emit=defineEmits<{changed:[];processing:[value:boolean]}>()
const popup=ref<{open:(type?:string)=>void;close:()=>void}|null>(null)
const{records,loading,busy,error,formError,dialog,kind,amount,reason,selected,channel,wallet,walletLoading,walletError,canIncrease,canDecrease,load,close,openCreate,canRespond,canPay,canSynchronize,prepare,openPay,confirm,synchronize}=useOrderAdjustments(()=>props.order,()=>emit('changed'))
/** 向订单页提供同一只读读取入口，不暴露调价或资金同步操作。 */
defineExpose({refresh:load})
const totals=computed(()=>adjustmentTotals(props.order)),processing=computed(()=>records.value.some(record=>record.id===props.order.active_adjustment_id&&adjustmentFundsPending(record)))
const dialogTitle=computed(()=>dialog.value==='create'?(kind.value==='increase'?'发起加价':'协商减价'):dialog.value==='pay'?'确认补款':dialog.value==='accept'?'确认同意方案':dialog.value==='reject'?'拒绝费用方案':'撤回费用方案')
const confirmLabel=computed(()=>dialog.value==='create'?'发送协商方案':dialog.value==='pay'?'确认并补款 ¥'+money(selected.value?.amount_cents):dialog.value==='accept'?'确认同意':dialog.value==='reject'?'确认拒绝':'确认撤回')
let popupVersion=0
/** 官方弹层按当前意图显示，快速关闭/切页后不能被旧nextTick重新打开。 */
async function syncPopup():Promise<void>{const current=++popupVersion;await nextTick();if(current!==popupVersion)return;if(dialog.value)popup.value?.open('bottom');else popup.value?.close()}
/** 点击遮罩的真实关闭同步取消未提交意图，处理中禁止关闭。 */
function popupChanged(event:{show:boolean}):void{if(!event.show&&dialog.value&&!busy.value)close()}
watch([dialog,popup],syncPopup,{flush:'post'});watch(processing,value=>emit('processing',value),{immediate:true})
</script>
<style scoped>
.order-adjustments{min-width:0;padding:38.4615rpx 0;border-bottom:1px solid var(--line-subtle)}.adjustment-heading,.adjustment-record-heading,.adjustment-sheet-heading{display:flex;align-items:center;justify-content:space-between;gap:23.0769rpx;min-width:0}.adjustment-title{font-size:30.7692rpx;line-height:46.1538rpx;font-weight:650}.adjustment-totals{margin:23.0769rpx 0}.adjustment-total-row,.adjustment-sheet-summary{display:flex;align-items:flex-start;justify-content:space-between;gap:30.7692rpx;min-width:0;padding:15.3846rpx 0;color:var(--muted);font-size:26.9231rpx;line-height:42.3077rpx;overflow-wrap:anywhere}.adjustment-total-net{border-top:1px solid var(--line-subtle);margin-top:7.6923rpx;padding-top:23.0769rpx;font-size:32.6923rpx;font-weight:650;color:var(--text)}.adjustment-positive{color:var(--accent)}.adjustment-new{display:flex;gap:23.0769rpx;margin:30.7692rpx 0}.adjustment-new-button{flex:1;min-width:0;gap:11.5385rpx}.adjustment-note{display:block;min-width:0;font-size:25rpx;line-height:42.3077rpx;color:var(--muted);overflow-wrap:anywhere}.adjustment-record{min-width:0;padding:30.7692rpx 0;border-bottom:1px solid var(--line-subtle)}.adjustment-record-pending{padding:30.7692rpx 23.0769rpx;margin:30.7692rpx 0;border:1px solid var(--line);border-radius:15.3846rpx;background:var(--surface)}.adjustment-record-heading{align-items:flex-start;flex-wrap:wrap}.adjustment-record-title{flex:1;min-width:250rpx;font-size:28.8462rpx;line-height:46.1538rpx;font-weight:650;overflow-wrap:anywhere}.adjustment-status{flex-shrink:0;font-size:23.0769rpx;line-height:46.1538rpx;color:var(--muted)}.adjustment-status-current{color:var(--accent)}.adjustment-reason{display:block;margin:19.2308rpx 0;font-size:26.9231rpx;line-height:46.1538rpx;white-space:pre-wrap;overflow-wrap:anywhere}.adjustment-consent{display:flex;flex-wrap:wrap;gap:30.7692rpx;margin-top:15.3846rpx;font-size:23.0769rpx;line-height:38.4615rpx;color:var(--muted)}.adjustment-record-actions{display:flex;align-items:center;justify-content:flex-end;gap:23.0769rpx;flex-wrap:wrap;margin-top:23.0769rpx;min-width:0}.adjustment-record-primary{min-width:207.6923rpx}.adjustment-secondary{color:var(--muted)}.adjustment-error,.adjustment-warning{display:block;margin:23.0769rpx 0;color:#e9b69d;font-size:26.9231rpx;line-height:46.1538rpx;white-space:pre-wrap;overflow-wrap:anywhere}.adjustment-footer-note{margin-top:30.7692rpx}.adjustment-sheet-scroll{width:100%;max-height:84vh;background:var(--surface);border-radius:34.6154rpx 34.6154rpx 0 0}.adjustment-sheet{width:100vw;max-width:600px;margin:0 auto;padding:46.1538rpx 30.7692rpx calc(46.1538rpx + env(safe-area-inset-bottom));box-sizing:border-box;color:var(--text);min-width:0}.adjustment-sheet-heading{margin-bottom:38.4615rpx}.adjustment-sheet-title{flex:1;min-width:0;font-size:40.3846rpx;line-height:57.6923rpx;font-weight:650}.adjustment-field{margin-top:46.1538rpx}.adjustment-field-label{display:block;font-size:26.9231rpx;line-height:46.1538rpx;color:var(--muted)}.adjustment-amount-field{display:flex;align-items:center;gap:15.3846rpx;height:115.3846rpx;border-bottom:1px solid var(--line);font-size:53.8462rpx;margin-top:15.3846rpx}.adjustment-amount-input{flex:1;min-width:0;height:92.3077rpx;color:var(--text);font-size:57.6923rpx}.adjustment-reason-input{height:246.1538rpx;margin-top:23.0769rpx;font-size:28.8462rpx;line-height:46.1538rpx}.adjustment-sheet-amount{display:block;margin:30.7692rpx 0;font-size:61.5385rpx;line-height:84.6154rpx;color:var(--accent);font-weight:650}.adjustment-channel-heading{margin-top:46.1538rpx;margin-bottom:23.0769rpx}.adjustment-channels{display:flex;flex-direction:column;gap:15.3846rpx}.adjustment-channel{display:flex;align-items:center;gap:23.0769rpx;width:100%;min-width:0;min-height:115.3846rpx;padding:23.0769rpx;border:1px solid var(--line);border-radius:15.3846rpx;background:transparent;color:var(--text);text-align:left;font-size:28.8462rpx}.adjustment-channel-selected{border-color:var(--accent)}.adjustment-channel-copy{flex:1;min-width:0;line-height:46.1538rpx}.adjustment-dialog-note{margin:38.4615rpx 0}.adjustment-dialog-actions{display:flex;align-items:center;justify-content:flex-end;gap:46.1538rpx;margin-top:61.5385rpx;min-width:0}.adjustment-confirm{min-width:276.9231rpx;max-width:85%;font-size:28.8462rpx}.adjustment-form-error{margin-top:30.7692rpx}
</style>
